      },
      {
        "description": "District average income (in thousands). Controls for community SES differences.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "Income"
        ]
      },
      {
        "description": "Computers per student (district-level). Controls for available technology/resources.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "ComputersPerStudent"
        ]
      },
      {
        "description": "District total enrollment. Controls for scale effects of district size.",
        "is_moderator": false,
